"""Shadowrun Sixth World Companion content (core-book rules only; the book's
optional rules are not used).

Metavariants and metasapients, HMHVV Infected, SURGE metagenic qualities,
new qualities and quality-path qualities, new contact archetypes, new critter
powers and gear PACKs. Numbers are the book's; descriptions are short
summaries written for this app.

Quality effect keys understood by ``sr.rules``:
  dr, phys_boxes, stun_boxes, overflow, attr_max (chosen attribute),
  attr_max_fixed {attr: n or "L"}, minor_actions, move [walk, sprint, per hit],
  natural_weapon {name, skill, dv, ar}, vision, essence_hole (per level),
  neoteny, injury_prone, jack_max, polyglot, cyber_psychosis, twitchy,
  loyalty_cap, favored_weapon, fitted_markup (per level), unarmed_ar,
  unarmed_physical, lifestyle_mult, wound_reduce.
"""

SOURCE = "Sixth World Companion"

ATTR_ORDER = ["Body", "Agility", "Reaction", "Strength", "Willpower", "Logic", "Intuition", "Charisma", "Edge"]


def _mx(*vals):
    return dict(zip(ATTR_ORDER, vals))


